function validate([head, root]) {
  if (!Array.isArray(head) || head.length < 1 || head.length > 100) return 'The list needs 1 to 100 nodes.';
  if (head.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'List values are whole numbers from 1 to 100.';
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs at least one node.';
  let nodes = 0;
  for (let i = 0; i < root.length; i++) {
    // Entry i (after the root) is a child slot of an earlier node, so enough nodes must come before it.
    if (i > 0 && nodes * 2 < i) return 'root is not a valid level-order tree.';
    const v = root[i];
    if (v === null) continue;
    if (!Number.isInteger(v) || v < 1 || v > 100) return 'Tree values are whole numbers from 1 to 100.';
    nodes++;
  }
  if (nodes > 2500) return 'The tree has at most 2500 nodes.';
  return null;
}

