function isSubPath(head, root) {
  const matchesFrom = (listNode, treeNode) => {
    if (listNode === null) return true;
    if (treeNode === null) return false;
    if (treeNode.val !== listNode.val) return false;
    return matchesFrom(listNode.next, treeNode.left) || matchesFrom(listNode.next, treeNode.right);
  };
  if (root === null) return false;
  if (matchesFrom(head, root)) return true;
  return isSubPath(head, root.left) || isSubPath(head, root.right);
}

