function isSubPath(head, root) {
  // A downward path of length m that ends at a node is the last m nodes of the root-to-node path.
  const values = [];
  for (let node = head; node; node = node.next) values.push(node.val);
  const path = [];
  let found = false;
  const walk = (node) => {
    if (!node || found) return;
    path.push(node.val);
    const offset = path.length - values.length;
    if (offset >= 0 && values.every((v, i) => v === path[offset + i])) found = true;
    walk(node.left);
    walk(node.right);
    path.pop();
  };
  walk(root);
  return found;
}

