function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? int(700, 1000) : int(1, 10);
  const alphabet = rand() < 0.75 ? int(1, 3) : 100;
  const value = () => int(1, alphabet);
  const deep = rand() < (large ? 0.6 : 0.3);
  const root = { val: value(), left: null, right: null };
  const nodes = [root];
  // Each new node fills a free child slot; "deep" trees prefer the newest slots and grow long paths.
  const free = [[root, 'left'], [root, 'right']];
  for (let k = 1; k < n; k++) {
    const index = deep ? free.length - 1 - Math.floor(rand() * Math.min(free.length, 2)) : Math.floor(rand() * free.length);
    const [parent, side] = free.splice(index, 1)[0];
    const node = { val: value(), left: null, right: null };
    parent[side] = node;
    nodes.push(node);
    free.push([node, 'left'], [node, 'right']);
  }
  const maxLength = large ? 100 : 4;
  let list;
  if (rand() < 0.65) {
    // Copy a real downward path; sometimes change its last value to make a near miss.
    const start = nodes[int(0, large ? Math.floor(n / 4) : n - 1)];
    const want = int(1, maxLength);
    list = [];
    for (let node = start; node && list.length < want;) {
      list.push(node.val);
      const children = [node.left, node.right].filter(Boolean);
      node = children.length ? children[int(0, children.length - 1)] : null;
    }
    if (rand() < 0.4) list[list.length - 1] = alphabet === 1 ? 2 : list[list.length - 1] % alphabet + 1;
  } else {
    list = Array.from({ length: int(1, maxLength) }, value);
  }
  // Serialize the tree level by level, then drop trailing nulls.
  const values = [];
  const queue = [root];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    values.push(node ? node.val : null);
    if (node) queue.push(node.left, node.right);
  }
  while (values[values.length - 1] === null) values.pop();
  return [list, values];
}
